cmd=['clang++','-arch','x86_64','-O2','-std=c++17','-fobjc-arc','-DKP_LIBRARY_REGISTRATION='+str(int(a.library_registration)),'-DKP_PIPELINE_NEGATIVE_TESTS='+str(int(a.negatives)),'-I',str(out),str(out/'registered_pipeline_contract_probe.mm'),str(lib/'libKeplerMetal.a'),'-Wl,-ObjC','-framework','Metal','-framework','Foundation','-o',str(out/'application')];r=subprocess.run(cmd,capture_output=True,text=True,timeout=45);(out/'build.stdout').write_text(r.stdout);(out/'build.stderr').write_text(r.stderr);(out/'commands.json').write_text(json.dumps([{'argv':cmd,'exit_code':r.returncode}],indent=2)+'\n');assert not r.returncode,r.stderr[-2500:]
(out/'inputs.json').write_text(json.dumps({'source_hashes':{n:sha(out/n)for n in ['KeplerCPUICB.h','registered_pipeline_contract_probe.mm','PipelineContractNegativeCases.inc','PipelineContractPendingReply.inc','ThreadLimitContractCases.inc','AutomaticQueueContractCases.inc','AutomaticQueueBlockingCase.inc','LibraryFunctionContractCases.inc','LibraryRegistrationInputsProbe.inc']},'assets_SHA256':m['assets_SHA256'],'runtime_SHA256':m['runtime_SHA256'],'static_library_SHA256':sha(lib/'libKeplerMetal.a'),'library_build_manifest_SHA256':sha(lib/'manifest.json'),'executable_SHA256':sha(out/'application'),'GPU_execution':False,'source_generator_SHA256':sha(__file__)},indent=2)+'\n');print(json.dumps({'status':'PASS','out':str(out)}))
